def M(t, enun, alts, gab, com, porque, pega, lab=None):
    assert len(alts) == 5 and len(porque) == 5 and 0 <= gab < 5
    return dict(tema=TEMA[t], enun=enun + (panel(lab) if lab else ""), alts=alts, gab=gab, com=com, porque=porque, pega=pega)


